learn=[('Compare the six explicit modes', 'Run default, dontAsk, acceptEdits, plan, auto and bypassPermissions against a fixed Read/Write task in a disposable directory. Compare the requested option with the actual mode reported by the SDK.'), ('Count callbacks and verify files', 'Default can send the unapproved Write to the denying callback. dontAsk rejects unresolved approval without a callback. acceptEdits can approve the eligible local write. Native results, PostToolUse events and host file checks establish the outcome.'), ('Review before a live mode switch', 'The plan-to-edit experiment pauses after the first real result. Review that result, approve or reject it, then observe the awaited setPermissionMode acknowledgement. Only an approved switch releases a second message on the same Query.'), ('Keep earlier rules and hooks in view', 'Bypass requires the explicit TypeScript opt-in and still respects earlier deny/ask rules and hooks. The bounded deny experiment scopes an Edit rule to the exact classroom output. This app exposes only Read and Write and never launches shell commands.'), ('Observe auto and omitted defaults honestly', 'Auto is model- and deployment-dependent. Its action result is not evidence that a classifier reviewed that particular Write. The omitted experiment records the actual starting mode. Current docs say newer SDK/headless runs default to default, which differs from the supplied slide and some type comments.'), ('Understand subagent inheritance', 'Current docs keep a parent plan mode restrictive even when a child requests acceptEdits; only default/dontAsk parents can apply eligible definition overrides. A child cannot enable bypass. This is a source-linked reference topic here; the app launches no subagents.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3129\n# Windows if needed: CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Install Node.js 24 or later and ensure API credit plus model access. On Windows configure Git Bash if required by the SDK. Python is needed only to regenerate student HTML.', 'node --version\nnpm --version'), ('Install and create your .env file', 'From presentations enter this app, install locked dependencies and preserve an existing .env. Enter your model key privately. No GitHub token or Managed Agents resource IDs are required.', 'cd .\\agent-sdk\\lesson29-permission-modes\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start the application', 'Keep the terminal running and open the printed URL. The fixed agent tasks run in disposable directories rather than the course source directory.', 'npm start\n# http://127.0.0.1:3129'), ('Compare explicit modes', 'Run the first six experiments and compare actual mode reports, Write attempts, callback counts and file contents. Auto is an observational case and does not expose a classifier trace.', 'npm run sample:env -- default\nnpm run sample:env -- dontAsk\nnpm run sample:env -- acceptEdits\nnpm run sample:env -- plan\nnpm run sample:env -- auto\nnpm run sample:env -- bypass'), ('Review and switch on one Query', 'In the web app choose Plan → review → acceptEdits, run it, review the actual first result and click Approve or Reject. Approval invokes setPermissionMode on the existing query before a second message is released. For an explicitly pre-approved CLI demonstration use the flag below.', 'npm run sample:env -- plan-to-edit --approve-plan'), ('Check deny and omitted behavior', 'Run the scoped deny under bypass, then omit permissionMode and inspect the actual reported starting mode. Do not assume an older slide’s default applies to this installed runtime.', 'npm run sample:env -- bypass-deny\nnpm run sample:env -- omitted\nnpm test')]
specs=[('Validate the experiment and prediction', 'src/modes.ts', 'export function validateConfig', 'The browser selects fixed classroom experiments. It cannot supply arbitrary permission modes, paths, commands or mode-change controls.', 0, 1, 7), ('Create the disposable workspace', 'src/workspace.ts', 'const root =', 'A verified temporary directory contains a read-only lesson fixture and an absent output. The host checks the fixture and output before bounded cleanup.', 1, 4, 7), ('Choose an explicit or omitted mode', 'src/agent.ts', '...(s.permissionMode', 'The omitted branch does not send permissionMode. Other branches pass an explicit value and supply the required TypeScript opt-in for bypass.', 1, 2, 5), ('Pass bounded operations to SDK permissions', 'src/agent.ts', 'const pass = hostAllows', 'The guard checks the exact fixture read and fixed output content, then passes valid requests without approving them. Mode and rule behavior remains observable.', 2, 1, 8), ('Count the actual callback decisions', 'src/agent.ts', 'canUseTool: async', 'The host denies unresolved calls. Compare callback counts with real native feedback, successful completion and file contents instead of assuming every mode prompts.', 2, 3, 7), ('Keep the streaming input alive', 'src/agent.ts', 'async function* input()', 'The first user message is followed by a gate. Only the reviewed switching experiment can release a second task on the same query.', 1, 2, 8), ('Start the actual SDK query', 'src/agent.ts', 'const run = query', 'One running Query handles the fixed task. The switching experiment reuses this object rather than starting a second session.', 1, 2, 3), ('Preserve the reported permission mode', 'src/agent.ts', 'reportedModes.push(message.permissionMode);', 'Record actual initialization and mode-status reports separately from configured values. An observed Write does not establish a hidden classifier invocation.', 2, 1, 7), ('Verify the pre-review file state', 'src/agent.ts', 'beforeSwitchFileCreated =', 'Before asking for review, check the actual output state. The browser receives the real first-turn result rather than a fabricated plan.', 1, 4, 6), ('Resolve a single-use review decision', 'src/review.ts', 'pending.set(id,', 'The review ID resolves one pending decision and is removed after use. Cancellation clears pending state. No mode change is requested on rejection.', 0, 1, 7), ('Await the actual mode-change control', 'src/agent.ts', 'await run.setPermissionMode', 'After approval, await acceptEdits on the same Query, record the acknowledgement and only then release the second user message.', 1, 2, 8), ('Verify output independently', 'src/workspace.ts', 'fileCreated: fileContents', 'Host checks compare the actual output with the expected classroom content and confirm that the fixture remains unchanged. Model text alone is not execution proof.', 4, 1, 5), ('Show the live review and acknowledgement', 'src/client.ts', 'if (e.type === "mode-change")', 'Render the actual mode-change event and explain that the second turn follows acknowledgement. Keep the real first-turn plan visible for review.', 1, 0, 5)]
document('/','Permission modes. <em>Review before action.</em>','Compare six modes and review a real plan before switching one live Query.','<div class="flow"><div><b>01 · Compare</b><p>Choose a mode and prediction</p></div><span>→</span><div><b>02 · Review</b><p>Approve or reject the actual plan</p></div><span>→</span><div><b>03 · Switch</b><p>Await the real SDK acknowledgement</p></div></div><section class="panel" id="controls"><h2>Explore permission modes</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Mode experiment</label><select id="mode"><option value="default">default · unapproved Write reaches callback</option><option value="dontAsk">dontAsk · unresolved Write denied</option><option value="acceptEdits">acceptEdits · eligible local Write approved</option><option value="plan">plan · compare read and attempted write</option><option value="auto">auto · observe actual mode and action result</option><option value="bypass">bypassPermissions · bounded classroom Write</option><option value="plan-to-edit">Plan → review → acceptEdits on one Query</option><option value="bypass-deny">Bypass with a scoped output deny</option><option value="omitted">Omitted permissionMode · inspect SDK report</option></select><label for="prediction">Predict or observe the actual task outcomes</label><select id="prediction"><option value="mixed">Mixed · some actions execute and some are denied</option><option value="execute">Execute · requested actions complete</option><option value="block">Block · no requested action completes</option><option value="observe">Observe · record runtime-dependent behavior</option></select><button id="run" class="primary" disabled>Run mode experiment →</button><p class="meta">Each run uses a fresh disposable directory and fixed Read/Write operations. Auto and omitted are observation cases. In Plan → review → acceptEdits, review the actual first result below and decide whether to enable the second turn.</p></section><section class="step" id="review-panel" hidden><h2>Review the actual plan before enabling edits</h2><div id="review-plan" class="markdown-body"></div><p id="review-status" class="note"></p><div class="actions"><button id="approve-plan" class="primary">Approve this plan and enable edits</button><button id="reject-plan">Reject plan</button></div><pre class="json-view"><code id="mode-change" class="language-json">{}</code></pre><p>The host requests acceptEdits only after approval and releases the second user message only after the SDK acknowledges that control call.</p></section><div class="workspace"><section class="panel" id="outcome"><h2 id="status" aria-live="polite">Ready</h2><p>Latest SDK-reported cost: <strong id="cost">—</strong></p><p class="meta">Session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p id="notice" class="note"></p></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Compare the requested permissionMode with the SDK-reported mode. Reference expectations are not an internal classifier trace.</p></section></div><section class="step" id="pipeline-panel"><h2>Six modes · reference</h2><p>These cards explain documented behavior. The app records actual reported modes, attempts, callback decisions and file state.</p><div class="grid"><article class="card"><h3>default</h3><p>No mode-based approval. Unapproved actions can reach canUseTool.</p></article><article class="card"><h3>dontAsk</h3><p>Deny actions that would prompt. Pre-approved and safe built-in actions may still run.</p></article><article class="card"><h3>acceptEdits</h3><p>Approve eligible file operations within the working-directory scope.</p></article><article class="card"><h3>plan</h3><p>Explore and plan; file writes are not auto-approved, even by allow entries.</p></article><article class="card"><h3>auto</h3><p>A classifier can review eligible actions. A successful file write does not prove a classifier call.</p></article><article class="card"><h3>bypassPermissions</h3><p>Broad automatic approval with an explicit TypeScript opt-in; earlier rules and hooks still apply.</p></article></div></section><section class="step" id="configuration-panel"><h2>Actual mode configuration</h2><label for="configuration-file">Configuration projection</label><select id="configuration-file"></select><pre class="json-view"><code id="configuration-content" class="language-json">{}</code></pre><p>Omitted means the option was genuinely absent. Explicit modes, scoped deny and TypeScript bypass opt-in appear as actually configured.</p></section><section class="step" id="discovery-panel"><h2>Actual SDK initialization and reported mode</h2><pre class="json-view"><code id="discovery" class="language-json">{}</code></pre><p>This is the SDK initialization payload. A requested mode and a reported mode are separate evidence.</p></section><section class="step" id="trace-panel"><h2>Actual hooks, callback calls and turns</h2><pre class="json-view"><code id="trace" class="language-json">{}</code></pre><p>Turn numbers distinguish planning from execution after a reviewed switch. The host guard passes only the fixed fixture read and output write.</p></section><section class="step" id="native-panel"><h2>Actual native tool feedback</h2><pre class="json-view"><code id="native" class="language-json">{}</code></pre><p>A denied Write can coexist with a successful model explanation. A model may also decline an edit while planning; inspect the actual attempt count.</p></section><section class="step" id="warning-panel"><h2>Actual SDK warning codes</h2><pre class="json-view"><code id="warnings" class="language-json">{}</code></pre><p>Warnings describe potentially shadowed callbacks. They are not a complete audit of mode decisions or classifier invocations.</p></section><section class="step" id="evidence-panel"><h2>Mode, session and independent file evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><p>Check actual mode reports, result/session IDs, switch acknowledgement, callback counts and host file checks. No classifier reasoning or unobserved internal steps are invented.</p></section><section class="step" id="comparison-panel"><h2>Compare this browser’s mode experiments</h2><p id="verdict">Predict execute, block, mixed or observe before running.</p><div class="table"><table><thead><tr><th>Experiment</th><th>Reference behavior</th><th>Prediction</th><th>Observed</th><th>Callbacks</th><th>Completed</th><th>Fixture</th></tr></thead><tbody id="history"></tbody></table></div><button id="download">Download redacted observations</button></section><section class="step" id="event-panel"><h2>Actual SDK messages</h2><ul id="events"></ul></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Compare mode reports, callback counts, review decisions and file outcomes.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. In plan-to-edit mode, respond to the review panel while the run is active. Rejecting leaves edits disabled. For auto, inspect actual reported mode and any runtime diagnostic. A successful file write does not prove classifier review.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','SDK session','Review broker','Lab files']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 29 · Compare → review → switch modes</text>']
